def validate_parens(paren_string: str) -> bool:
    """ Given a string of parentheses, return True if it is valid (ie. is a proper subset of the possible nested parentheses). 
    False otherwise. This is a valid solution: ((()(())))
        This is not valid: ((())
        This is not valid: (()(()

    >>> validate_parens('(()())')
    True
    >>> validate_parens('(((())'))
    False
    """
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack


