    """ A recursive function that counts maximum number of nesting of parentheses with a string of parentheses.

    >>> max_level('(')
    0
    >>> max_level('()')
    1
    >>> max_level('((()))')
    4
    >>> max_level('()((()))')
    5
    """
    if not paren_string:
        return 0
    elif paren_string[0] == '(':
        return 1 + max_level(paren_string[1:])
    else:
        return 0 + max_level(paren_string[1:])

    return [len(parens.split()) for parens in paren_string.split(" ") if parens != ""]


