def round_number(number: float, decimal: int = 0) -> float:
    """ Given a positive floating point number and an integer
    decimal, it can be decomposed into and integer part (largest integer smaller
    than given number) and decimals (leftover part always smaller than 1).

    Return the number rounded to the decimal (ex. if `decimal == 0` it will return
    the original number, if `decimal == 2` it will return the number rounded to
    2 decimal places). If the `decimal` is less than 0, it should return the
    original number as it is.

    See also:
        https://www.w3schools.com/python/ref_func_round.asp
    """
    if decimal < 0:
        return number
    if decimal == 0:
        return truncate_number(number)
    else:
        return round(number, decimal)

