def string_contains_any(string: str, chars: List[str]) -> bool:
    """ Checks whether the input string contains any of the characters
    given in chars.
    """
    return any(c in string for c in chars)


def reverse_string(string: str) -> str:
    """ Reverses an input string."""
    if not string:
        return string
    if len(string) == 1:
        return string
    return reverse_string(string[1:]) + string[0]


def string_has_substring(string: str, substring: str) -> bool:
    """ Checks whether the input string contains the given substring.
    """
    return substring in string
